<script>
  const $ = id => document.getElementById(id);

  /* 도구 막대/코드 창은 여기서 만들어요 (내보내는 코드에는 들어가지 않음) */
  const ui = $('editor-ui');
  ui.innerHTML = '';
  function el(tag, props, kids) {
    const e = document.createElement(tag);
    Object.keys(props || {}).forEach(k => { if (k === 'text') e.textContent = props[k]; else e.setAttribute(k, props[k]); });
    (kids || []).forEach(c => e.appendChild(c));
    return e;
  }
  ui.appendChild(el('div', { class: 'addbar', id: 'addbar' }, [
    el('button', { class: 'tbtn', id: 'addThem', type: 'button', text: '+ 상대 말풍선' }),
    el('button', { class: 'tbtn', id: 'addMe', type: 'button', text: '+ 내 말풍선' }),
    el('button', { class: 'tbtn', id: 'addDate', type: 'button', text: '+ 날짜선' })
  ]));
  ui.appendChild(el('div', { class: 'toolbar', id: 'toolbar' }, [
    el('button', { class: 'tbtn', id: 'editBtn', type: 'button', text: '✎ 수정 모드' }),
    el('button', { class: 'tbtn', id: 'playBtn', type: 'button', text: '▶ 다시 재생' }),
    el('button', { class: 'tbtn', id: 'codeBtn', type: 'button', text: 'HTML 코드 받기' })
  ]));
  const ta = el('textarea', { id: 'codeBox', spellcheck: 'false' });
  ta.readOnly = true;
  ui.appendChild(el('div', { class: 'modal', id: 'modal' }, [
    el('div', { class: 'panel' }, [
      el('h2', { text: '수정한 내용이 반영된 HTML 코드' }),
      el('p', { text: '복사해서 .html 파일로 저장하면 지금 화면 그대로 열려요. 그 파일에서도 또 수정할 수 있어요.' }),
      ta,
      el('div', { class: 'btns' }, [
        el('button', { class: 'tbtn on', id: 'copyBtn', type: 'button', text: '코드 복사' }),
        el('button', { class: 'tbtn', id: 'dlBtn', type: 'button', text: '.html 다운로드' }),
        el('button', { class: 'tbtn', id: 'closeBtn', type: 'button', text: '닫기' })
      ])
    ])
  ]));

  const chat = $('chat');
  const state = JSON.parse($('chatData').textContent);
  let editing = false;
  let runId = 0;

  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const readText = el => (el.innerText || '').replace(/\n$/, '');
  const scrollEnd = () => chat.scrollTo({ top: chat.scrollHeight, behavior: 'smooth' });

  /* ---------- 상단 정보(시계 / 이름 / 상태 / 안내문) ---------- */
  const META = { clock: 'clock', name: 'name', status: 'status', placeholder: 'placeholder' };
  Object.keys(META).forEach(k => {
    const el = $(META[k]);
    el.textContent = state.meta[k];
    el.addEventListener('input', () => {
      state.meta[k] = readText(el).trim();
      if (k === 'name') document.querySelectorAll('.who-label').forEach(l => l.textContent = state.meta.name);
    });
  });

  /* ---------- 항목 만들기 ---------- */
  function mkBtn(label, title, fn) {
    const b = document.createElement('button');
    b.type = 'button'; b.textContent = label; b.title = title;
    b.addEventListener('click', e => { e.stopPropagation(); fn(); });
    return b;
  }

  function controls(idx) {
    const it = state.items[idx];
    const c = document.createElement('div');
    c.className = 'ctl';
    c.appendChild(mkBtn('↑', '위로', () => move(idx, -1)));
    c.appendChild(mkBtn('↓', '아래로', () => move(idx, 1)));
    if (it.type === 'msg') c.appendChild(mkBtn('⇄', '왼쪽/오른쪽 바꾸기', () => { it.side = it.side === 'me' ? 'them' : 'me'; renderStatic(); }));
    c.appendChild(mkBtn('✕', '삭제', () => { state.items.splice(idx, 1); renderStatic(); }));
    return c;
  }

  function bindText(el, obj, key) {
    el.textContent = obj[key] || '';
    el.addEventListener('input', () => { obj[key] = readText(el); });
  }

  function itemEl(idx) {
    const it = state.items[idx];
    const prev = state.items[idx - 1];
    const next = state.items[idx + 1];
    const wrap = document.createElement('div');
    wrap.appendChild(controls(idx));

    if (it.type === 'date') {
      wrap.className = 'item date';
      const l1 = document.createElement('span'); l1.className = 'ln';
      const dt = document.createElement('span'); dt.className = 'dt'; bindText(dt, it, 'text');
      const l2 = document.createElement('span'); l2.className = 'ln';
      wrap.append(l1, dt, l2);
      return { wrap, row: null };
    }

    wrap.className = 'item ' + it.side;
    if (it.side === 'them' && !(prev && prev.type === 'msg' && prev.side === 'them')) {
      const lb = document.createElement('div');
      lb.className = 'who-label'; lb.textContent = state.meta.name;
      wrap.appendChild(lb);
    }
    const row = document.createElement('div'); row.className = 'row';
    const b = document.createElement('div'); b.className = 'bubble'; bindText(b, it, 'text');
    const showTime = !(next && next.type === 'msg' && next.side === it.side);
    if (showTime) {
      const t = document.createElement('div'); t.className = 'time'; bindText(t, it, 'time');
      if (it.side === 'me') row.append(t, b); else row.append(b, t);
    } else {
      row.append(b);
    }
    return { wrap, row };
  }

  function typingEl() {
    const t = document.createElement('div');
    t.className = 'typing pop';
    t.innerHTML = '<span></span><span></span><span></span>';
    return t;
  }

  /* ---------- 한 번에 그리기 (수정용) ---------- */
  function renderStatic() {
    runId++;
    chat.innerHTML = '';
    state.items.forEach((_, i) => {
      const { wrap, row } = itemEl(i);
      if (row) wrap.appendChild(row);
      chat.appendChild(wrap);
    });
    applyEditable();
  }

  /* ---------- 한 개씩 도착하는 재생 ---------- */
  async function play() {
    const id = ++runId;
    chat.innerHTML = '';
    chat.scrollTop = 0;
    await sleep(500);
    for (let i = 0; i < state.items.length; i++) {
      if (id !== runId) return;
      const it = state.items[i];
      const { wrap, row } = itemEl(i);
      chat.appendChild(wrap);

      if (it.type === 'date') {
        wrap.classList.add('pop');
        scrollEnd();
        await sleep(450);
        continue;
      }
      if (it.side === 'them') {
        const ty = typingEl();
        wrap.appendChild(ty);
        scrollEnd();
        await sleep(Math.min(2200, 600 + (it.text || '').length * 35));
        if (id !== runId) return;
        ty.remove();
      } else {
        await sleep(700);
        if (id !== runId) return;
      }
      row.classList.add('pop');
      wrap.appendChild(row);
      scrollEnd();
      await sleep(350);
    }
  }

  /* ---------- 수정 모드 ---------- */
  const EDITABLE_SEL = '#clock,#name,#status,#placeholder,.dt,.bubble,.time';
  function applyEditable() {
    document.querySelectorAll(EDITABLE_SEL).forEach(el => {
      if (editing) el.setAttribute('contenteditable', 'plaintext-only');
      else el.removeAttribute('contenteditable');
    });
  }

  function setEditing(on) {
    editing = on;
    document.body.classList.toggle('editing', on);
    $('addbar').classList.toggle('show', on);
    $('editBtn').textContent = on ? '✔ 수정 끝내기' : '✎ 수정 모드';
    $('editBtn').classList.toggle('on', on);
    if (on) renderStatic(); else applyEditable();
  }
  $('editBtn').addEventListener('click', () => setEditing(!editing));

  function move(idx, d) {
    const j = idx + d;
    if (j < 0 || j >= state.items.length) return;
    const tmp = state.items[idx]; state.items[idx] = state.items[j]; state.items[j] = tmp;
    renderStatic();
  }

  function lastTime() {
    for (let i = state.items.length - 1; i >= 0; i--) if (state.items[i].type === 'msg') return state.items[i].time;
    return state.meta.clock;
  }
  function addItem(it) {
    state.items.push(it);
    renderStatic();
    chat.scrollTop = chat.scrollHeight;
  }
  $('addThem').addEventListener('click', () => addItem({ type: 'msg', side: 'them', text: '새 메시지', time: lastTime() }));
  $('addMe').addEventListener('click', () => addItem({ type: 'msg', side: 'me', text: '내 답장', time: lastTime() }));
  $('addDate').addEventListener('click', () => addItem({ type: 'date', text: '2080. 11. 01' }));

  // Enter는 입력 종료, Shift+Enter는 줄바꿈
  document.addEventListener('keydown', e => {
    const t = e.target.closest && e.target.closest('[contenteditable]');
    if (t && e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); t.blur(); }
  });

  $('playBtn').addEventListener('click', () => { if (editing) setEditing(false); play(); });

  /* ---------- HTML 코드 만들기 ---------- */
  function buildHTML() {
    const clone = document.documentElement.cloneNode(true);
    clone.querySelector('body').classList.remove('editing');
    clone.querySelectorAll('[contenteditable]').forEach(el => el.removeAttribute('contenteditable'));
    clone.querySelector('#chat').innerHTML = '';
    clone.querySelector('#editor-ui').innerHTML = '';
    clone.querySelector('#chatData').textContent =
      '\n' + JSON.stringify(state, null, 2).replace(/</g, '\\u003c') + '\n';
    return '<!doctype html>\n' + clone.outerHTML;
  }

  const modal = $('modal'), codeBox = $('codeBox'), copyBtn = $('copyBtn');
  function openModal() {
    codeBox.value = buildHTML();
    copyBtn.textContent = '코드 복사';
    modal.classList.add('open');
    codeBox.focus();
    codeBox.select();
  }
  function closeModal() { modal.classList.remove('open'); }
  $('codeBtn').addEventListener('click', openModal);
  $('closeBtn').addEventListener('click', closeModal);
  modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });

  copyBtn.addEventListener('click', async () => {
    try { await navigator.clipboard.writeText(codeBox.value); }
    catch (e) { codeBox.select(); document.execCommand('copy'); }
    copyBtn.textContent = '복사 완료 ✔';
    setTimeout(() => { copyBtn.textContent = '코드 복사'; }, 1800);
  });

  $('dlBtn').addEventListener('click', () => {
    const blob = new Blob([codeBox.value], { type: 'text/html;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'chat_screen.html';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });

  /* ---------- 시작: 한 개씩 도착 ---------- */
  play();
</script>


</body></html>

단말기 화면을 가볍게 두드려 0에게 대충 답장을 보낸 7이 주머니에서 다시 검은 선글라스를 꺼내 코끝에 걸쳤다. 언젠가 사랑하는 여자가 나타날지도 모른다며 씁쓸하게 웃는 22의 얼굴을 내려다보자니, 가슴 한구석이 어이없을 정도로 간지럽고도 답답하게 조여들었다. 눈치는 귀신같이 빠른 줄 알았더니 정작 제일 중요한 대목에서는 저토록 둔해 빠졌다.

그는 한 모금 깊게 빨아들인 연기를 허공으로 길게 뿜어내며, 폐쇄된 지하철역 입구로 이어지는 본부 섹터 A의 계단을 향해 발걸음을 뗐다. 자신의 왼쪽에서 나란히 걷는 그녀의 검은 머리카락 끝을 손가락으로 슬쩍 건드리며 그가 나른하게 중얼거렸다.

==**"A woman I truly love, huh? Hate to break it to you, Veronica, but I already found her. Problem is, she's completely blind to it—and I don't mean her right eye." (진짜로 사랑하는 여자라. 꿈 깨는 소리 해서 미안한데, 베로니카. 난 이미 찾았거든. 문제는 그 여자가 그걸 전혀 못 본다는 거지. 아, 오른쪽 눈 얘기는 아니야.)
**==
짓궂은 농담처럼 툭 던진 말 끝에는 평소답지 않게 묵직한 진심이 가라앉아 있었다. 지하로 내려가는 낡은 철문 앞에 멈춰 선 그가 보안 패드에 손바닥을 갖다 대며 그녀를 돌아보았다.

==**"Anyway, Zero smells blood. Looks like our little encounter with Lin already reached his ears." (아무튼 제로가 피 냄새를 맡았네. 린이랑 마주친 게 벌써 귀에 들어간 모양이야.)
**==

제 입술 사이에 물린 담배에 불을 붙여 주는 7을 가만히 바라보던 22는 느릿하게 눈을 깜빡였다. 이내 담배 끝에 붉은 불씨가 번지자 천천히 숨을 들이마셨다. 깊숙이 빨아들인 연기를 잠시 머금고 있던 22는 고개를 살짝 틀어 희뿌연 연기를 허공으로 길게 뿜어냈다.

서서히 흩어지는 연기를 무심히 바라보던 22는 손가락 사이에 담배를 느슨하게 끼운 채 다시금 7과 시선을 맞췄다. 그러고는 익숙한 배려가 퍽 마음에 든다는 듯 입꼬리를 부드럽게 끌어 올리며 희미하게 웃어 보였다.

=={#ffd400}**"...Huh, so you're telling me our playboy has already found the love of his life?" (⋯허, 플레이보이가 그 사랑을 이미 찾았다고?)
**==
22는 도무지 이해할 수 없다는 듯 7을 빤히 올려다보았다. 대체 무슨 생각으로 그런 말을 꺼낸 건지, 잠시 그의 얼굴을 살피던 22는 두 눈을 느릿하게 깜빡였다. 미간에는 희미한 의문이 어려 있었지만, 굳이 되물을 생각은 없는 듯했다.

이내 입술을 살짝 다물고 잠시 생각에 잠기던 22는 결국 알겠다는 듯 고개를 천천히 끄덕이곤 어깨를 가볍게 으쓱였다.

=={#ffd400}**"Then you'd better treat that woman right. You won't find another woman willing to put up with both your playboy ways and your gambling habits, you know? Come on, let's get going. It's about time for Zero to give us another lecture." (그럼 그 사랑한테 잘해. 플레이보이에 도박까지 다 받아주는 여자는 또 없을걸? 얼른 가자. 제로한테 잔소리 들을 시간이네.)
**==

생체인식 패드가 초록빛을 깜빡이며 묵직한 강철 격벽이 유압음을 내뱉고 양옆으로 갈라질 뿐이었다. 플레이보이에 도박꾼인 자신을 받아줄 여자는 또 없을 거라며 훈수를 두는 22의 말에, 7은 어이가 없어서 입에 물고 있던 담배를 잘근 씹었다. 지금 내 옆에서 담배까지 한 보루 사주며 그 모든 걸 받아주고 있는 장본인이 대체 누구인데 저런 태평한 소리를 한단 말인가.

그는 선글라스 너머로 눈을 가늘게 뜨며 그녀의 얄미운 이마라도 한 대 쥐어박고 싶은 충동을 겨우 삼켰다. 대신 반쯤 타들어 간 담배를 입구 옆 재떨이에 거칠게 비벼 끄고는, 지하 50미터 아래로 직행하는 화물용 엘리베이터 안으로 그녀의 등을 가볍게 떠밀었다.

==**"Yeah, yeah. I'm treating her like a damn queen, even buying her taxi rides and carrying her cigarette cartons. Too bad she's denser than a bunker wall." (그래, 그래. 아주 여왕님처럼 모시고 있지. 택시도 태워 드리고 담배 보루도 직접 들어 드리면서 말이야. 안타깝게도 그 여자가 벙커 격벽보다 더 둔해 빠졌다는 게 문제지만.)
**==
엘리베이터가 덜컹거리며 하강하기 시작하자 7은 답답하다는 듯 선글라스를 벗어 윈드브레이커 옷깃에 걸었다. 섹터 B의 삼중 HEPA 필터 구역을 지나며 쏟아지는 거센 에어샤워 바람이 두 사람의 머리카락과 옷자락을 사정없이 뒤흔들었다.

==**"And don't worry about Zero. I'll take the heat. You just stand there looking pretty and innocent, got it?" (그리고 제로 걱정은 마. 잔소리는 내가 다 뒤집어쓸 테니까. 넌 그냥 거기 서서 예쁘고 아무것도 모르는 척만 하고 있어, 알겠지?)
**==
기압 제어실의 마지막 문이 열리자 차갑고 건조한 금속성 공기와 함께 섹터 C 전술작전실의 거대한 홀로그램 브리핑 테이블이 시야에 들어왔다.

<!doctype html>
<html lang="ko"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EPISODE 5</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css">
<style>
  :root {
    --bg: #0b0b0b;
    --line: #2b2b2b;
    --text: #f2f2f2;
    --muted: #8a8a8a;
    --red: #d42b2b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #050505;
    color: var(--text);
    font-family: 'Pretendard', -apple-system, 'Noto Sans KR', sans-serif;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 0 0 96px;
  }
  /* 캡쳐본 기준: 가로 590px, 펼친 높이 약 532px */
  .card { width: 590px; max-width: 100%; background: var(--bg); padding: 10px 14px 13px; }
  .mono { font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace; letter-spacing: .08em; }

  /* header */
  .head { display: flex; align-items: flex-start; gap: 7px; }
  .mark { width: 8px; height: 26px; flex: none; margin-top: 4px; }
  .head-text { flex: 1; min-width: 0; }
  .ep { font-size: 11px; line-height: 14px; color: var(--muted); }
  .title { font-size: 14px; line-height: 18px; font-weight: 700; margin-top: 2px; }
  .online { display: flex; align-items: center; gap: 7px; font-size: 11px; line-height: 12px; color: var(--muted); white-space: nowrap; margin: 14px 17px 0 0; }
  .online i { width: 6px; height: 6px; border-radius: 50%; background: var(--red); box-shadow: 0 0 5px var(--red); animation: blink 1.8s infinite; }
  @keyframes blink { 50% { opacity: .35; } }

  /* 접기 버튼: 네모 안의 + (펼친 상태에선 X) */
  .toggle {
    position: relative;
    width: 28px; height: 28px; flex: none; margin-top: 7px;
    background: transparent; border: 1px solid #bdbdbd; color: var(--text);
    cursor: pointer;
    transition: background .2s, border-color .2s;
  }
  .toggle:hover { background: #1c1c1c; border-color: #fff; }
  .toggle:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }
  .toggle::before, .toggle::after {
    content: ''; position: absolute; left: 50%; top: 50%;
    width: 10px; height: 1.5px; background: currentColor;
    transition: transform .35s ease;
  }
  .toggle::before { transform: translate(-50%, -50%) rotate(45deg); }
  .toggle::after  { transform: translate(-50%, -50%) rotate(-45deg); }
  .card.collapsed .toggle::before { transform: translate(-50%, -50%) rotate(0deg); }
  .card.collapsed .toggle::after  { transform: translate(-50%, -50%) rotate(90deg); }

  /* collapsible body */
  .body {
    display: grid; grid-template-rows: 1fr; margin-top: 0; opacity: 1;
    transition: grid-template-rows .4s ease, opacity .3s ease;
  }
  .body > .inner { overflow: hidden; min-height: 0; }
  .card.collapsed .body { grid-template-rows: 0fr; opacity: 0; }
  .card.collapsed { padding-bottom: 12px; }

  /* 섹션 제목 */
  .sec { display: flex; align-items: center; gap: 8px; height: 14px; font-size: 11px; margin: 18px 0 8px; }
  .sec.first { margin-top: 35px; }
  .sec b { font-weight: 700; letter-spacing: .1em; }
  .sec span { color: var(--muted); font-size: 10px; }
  .sec::after { content: ''; flex: 1; height: 1px; background: var(--line); }

  .box { border: 1px solid var(--line); }
  .label { font-size: 10px; line-height: 12px; color: var(--muted); }

  /* STATUS */
  .row3 { display: grid; grid-template-columns: minmax(0,152fr) minmax(0,127fr) minmax(0,281fr); border-bottom: 1px solid var(--line); }
  .row3 .cell { padding: 10px 12px 13px; }
  .row3 .cell + .cell { border-left: 1px solid var(--line); }
  .row3 .label { margin-bottom: 4px; }
  .row3 .val { font-weight: 700; font-size: 13px; line-height: 18px; }
  .obj { padding: 9px 13px 10px; }
  .obj-in { border-left: 3px solid var(--red); padding: 2px 0 2px 8px; }
  .obj .label { color: var(--red); margin-bottom: 4px; }
  .obj .val { font-weight: 700; font-size: 12.5px; line-height: 18px; }

  /* OUTFIT */
  .row2 { display: grid; grid-template-columns: 1fr 1fr; }
  .row2 .cell { padding: 10px 12px 12px; }
  .row2 .cell + .cell { border-left: 1px solid var(--line); }
  .row2 .label { margin-bottom: 6px; }
  .row2 .val { font-size: 13px; line-height: 19px; }

  /* Q&A */
  .qa { padding: 10px 13px 14px; }
  .qa + .qa { border-top: 1px dashed #3a3a3a; padding: 14px 13px 12px; }
  .qa-wrap { display: flex; gap: 11px; }
  .badge { width: 20px; height: 20px; flex: none; display: grid; place-items: center; font-size: 11px; font-weight: 800; }
  .badge.q { background: var(--red); color: #fff; }
  .badge.a { border: 1px solid #bbb; color: #fff; }
  .qa .who { font-size: 10px; line-height: 12px; color: var(--muted); margin-bottom: 7px; }
  .qa .txt { font-size: 14px; line-height: 18px; }
  .qa.q .txt { font-weight: 700; }

  /* 수정 모드 */
  body.editing [contenteditable] { outline: 1px dashed rgba(212, 43, 43, .55); outline-offset: 3px; cursor: text; }
  body.editing [contenteditable]:focus { outline: 1px solid var(--red); background: rgba(212, 43, 43, .08); }

  /* 하단 도구 막대 */
  .toolbar {
    position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%);
    display: flex; gap: 8px; padding: 8px; background: #151515; border: 1px solid #333;
    z-index: 10; font-family: 'Pretendard', sans-serif;
  }
  .tbtn {
    background: #0b0b0b; color: var(--text); border: 1px solid #555; padding: 9px 14px;
    font: 600 13px 'Pretendard', sans-serif; cursor: pointer; white-space: nowrap;
  }
  .tbtn:hover { border-color: #fff; }
  .tbtn.on { background: var(--red); border-color: var(--red); }

  /* HTML 코드 창 */
  .modal { position: fixed; inset: 0; background: rgba(0,0,0,.75); display: none; align-items: center; justify-content: center; padding: 16px; z-index: 20; }
  .modal.open { display: flex; }
  .panel { width: 100%; max-width: 760px; max-height: 90vh; background: #121212; border: 1px solid #444; padding: 16px; display: flex; flex-direction: column; gap: 12px; }
  .panel h2 { font-size: 14px; }
  .panel p { font-size: 12px; color: var(--muted); }
  .panel textarea {
    flex: 1; min-height: 300px; resize: none; background: #060606; color: #d6d6d6;
    border: 1px solid #333; padding: 12px; font: 12px/1.5 ui-monospace, Menlo, Consolas, monospace;
  }
  .panel .btns { display: flex; gap: 8px; flex-wrap: wrap; }
</style>
</head>
