<script>
  /* 도구 막대/코드 창은 여기서 만들어요 (내보내는 코드에는 들어가지 않음) */
  const ui = document.getElementById('editor-ui');
  ui.innerHTML = '';
  function el(tag, props, kids) {
    const e = document.createElement(tag);
    Object.keys(props || {}).forEach(k => { if (k === 'text') e.textContent = props[k]; else e.setAttribute(k, props[k]); });
    (kids || []).forEach(c => e.appendChild(c));
    return e;
  }
  ui.appendChild(el('div', { class: 'toolbar', id: 'toolbar' }, [
    el('button', { class: 'tbtn', id: 'editBtn', type: 'button', text: '✎ 수정 모드' }),
    el('button', { class: 'tbtn', id: 'codeBtn', type: 'button', text: 'HTML 코드 받기' })
  ]));
  const ta = el('textarea', { id: 'codeBox', spellcheck: 'false' });
  ta.readOnly = true;
  ui.appendChild(el('div', { class: 'modal', id: 'modal' }, [
    el('div', { class: 'panel' }, [
      el('h2', { text: '수정한 내용이 반영된 HTML 코드' }),
      el('p', { text: '복사해서 .html 파일로 저장하면 지금 화면 그대로 열려요. 그 파일에서도 또 수정할 수 있어요.' }),
      ta,
      el('div', { class: 'btns' }, [
        el('button', { class: 'tbtn on', id: 'copyBtn', type: 'button', text: '코드 복사' }),
        el('button', { class: 'tbtn', id: 'dlBtn', type: 'button', text: '.html 다운로드' }),
        el('button', { class: 'tbtn', id: 'closeBtn', type: 'button', text: '닫기' })
      ])
    ])
  ]));

  const card = document.getElementById('card');
  const toggleBtn = document.getElementById('toggle');
  const editBtn = document.getElementById('editBtn');
  const codeBtn = document.getElementById('codeBtn');
  const modal = document.getElementById('modal');
  const codeBox = document.getElementById('codeBox');
  const copyBtn = document.getElementById('copyBtn');
  const dlBtn = document.getElementById('dlBtn');
  const closeBtn = document.getElementById('closeBtn');

  const KEY = 'ep5-collapsed';
  const EDIT_SEL = '.title,.ep,.online-text,.val,.txt,.who,.label,.sec b,.sec span';

  /* ---- 접기 / 펼치기 ---- */
  function setCollapsed(v) {
    card.classList.toggle('collapsed', v);
    toggleBtn.setAttribute('aria-expanded', String(!v));
    try { localStorage.setItem(KEY, v ? '1' : '0'); } catch (e) {}
  }
  toggleBtn.addEventListener('click', () => setCollapsed(!card.classList.contains('collapsed')));
  try { if (localStorage.getItem(KEY) === '1') setCollapsed(true); } catch (e) {}

  /* ---- 수정 모드 ---- */
  function setEditing(on) {
    document.body.classList.toggle('editing', on);
    document.querySelectorAll(EDIT_SEL).forEach(el => {
      if (on) el.setAttribute('contenteditable', 'true');
      else el.removeAttribute('contenteditable');
    });
    editBtn.textContent = on ? '✔ 수정 끝내기' : '✎ 수정 모드';
    editBtn.classList.toggle('on', on);
    if (on) setCollapsed(false);
  }
  editBtn.addEventListener('click', () => setEditing(!document.body.classList.contains('editing')));

  // 붙여넣기는 글자만, Enter는 입력 종료, Shift+Enter로 줄바꿈
  document.addEventListener('paste', e => {
    const t = e.target.closest && e.target.closest('[contenteditable]');
    if (!t) return;
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData('text/plain');
    document.execCommand('insertText', false, text);
  });
  document.addEventListener('keydown', e => {
    const t = e.target.closest && e.target.closest('[contenteditable]');
    if (t && e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); t.blur(); }
  });

  /* ---- HTML 코드 만들기 ---- */
  function buildHTML() {
    const clone = document.documentElement.cloneNode(true);
    clone.querySelector('body').classList.remove('editing');
    clone.querySelectorAll('[contenteditable]').forEach(el => el.removeAttribute('contenteditable'));
    clone.querySelector('#card').classList.remove('collapsed');
    clone.querySelector('#toggle').setAttribute('aria-expanded', 'true');
    clone.querySelector('#editor-ui').innerHTML = '';
    return '<!doctype html>\n' + clone.outerHTML;
  }

  function openModal() {
    codeBox.value = buildHTML();
    copyBtn.textContent = '코드 복사';
    modal.classList.add('open');
    codeBox.focus();
    codeBox.select();
  }
  function closeModal() { modal.classList.remove('open'); }

  codeBtn.addEventListener('click', openModal);
  closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });

  copyBtn.addEventListener('click', async () => {
    const text = codeBox.value;
    try {
      await navigator.clipboard.writeText(text);
    } catch (e) {
      codeBox.select();
      document.execCommand('copy');
    }
    copyBtn.textContent = '복사 완료 ✔';
    setTimeout(() => { copyBtn.textContent = '코드 복사'; }, 1800);
  });

  dlBtn.addEventListener('click', () => {
    const blob = new Blob([codeBox.value], { type: 'text/html;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'episode5_card.html';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });
</script>


</body></html>

제 무릎 사이로 다리를 밀어 넣듯 가까이 자리를 잡는 7의 행동에도 22는 별다른 동요를 보이지 않았다. 이내 그가 손을 뻗어 제 턱을 감싸 쥐고 고개를 옆으로 돌리자, 순순히 그 손길에 따라 얼굴을 틀었다. 귀의 상태를 확인하려는 의도를 알아챈 듯 얌전히 움직임을 멈춘 채 느릿하게 눈을 깜빡였다.

22는 제 귀를 유심히 살피는 7을 곁눈질하다가 입가에 희미한 미소를 머금었다. 걱정스러운 그의 태도가 새삼스럽지도 않다는 듯, 이내 어깨를 가볍게 으쓱이며 아무렇지 않은 목소리로 천천히 입을 열었다.

=={#ffd400}**"I don't understand why you're getting so angry about my death, 7. You knew I was always like this, didn't you?" (내 죽음에 왜 이렇게 7이 화를 내는지 모르겠네. 원래 이런 사람인 거 알고 있었잖아, 아니야?)**==

검이경의 작은 불빛이 22의 귓속을 비추고 다행히 고막에 별다른 이상이 없음을 확인한 7이 기구의 전원을 껐을 뿐이었다. 원래 이런 사람인 걸 알지 않느냐는 무심한 반문이 정적 속에 흩어졌다. 7은 검이경을 옆 트레이에 툭 던져놓고는 그녀의 턱을 쥐고 있던 손을 천천히 옮겨 하얀 뺨을 감싸 쥐었다.

입사 동기였던 4년 전부터 제 목숨을 초개처럼 여기던 여자였다. 하지만 강습타격대에서 함께 구르던 시절과 지금은 달라도 너무 달랐다. 그의 엄지손가락이 22의 입술 끝을 지그시 누르며 쓸어내렸다. 선글라스가 없는 연회색 눈동자가 지척에서 그녀의 검은 눈동자를 집요하게 파고들었다.

==**"Yeah, I knew. For four damn years, I watched you act like your life is disposable. Back then, I thought I could just stand next to you and block the bullets myself." (그래, 알았지. 빌어먹을 4년 내내 네가 네 목숨을 일회용품처럼 굴리는 걸 지켜봤으니까. 그땐 그냥 내가 네 옆에 서서 총알을 대신 막아주면 그만이라고 생각했어.)
**==
7은 상체를 더 깊이 숙여 그녀와 이마가 닿을 듯한 거리까지 숨결을 좁혔다. 화상 흉터가 자리한 오른쪽 얼굴이 형광등 불빛 아래 적나라하게 드러났고, 평소라면 절대 보이지 않았을 절박하고도 달뜬 열기가 그의 낯을 붉게 물들이고 있었다.

==**"Then you lost your eye, Veronica. And I realized if you actually die, there's nobody left in this messed up world to call me Axion. So yeah, I get angry. Because I'm the idiot who's gonna be left behind missing you like crazy." (그러다 네가 눈을 잃었잖아, 베로니카. 그때 깨달았어. 네가 진짜 죽어버리면, 이 좆같은 세상에서 날 악시온이라고 불러줄 사람이 아예 사라진다는 걸. 그래, 그래서 화가 나. 네가 죽으면 미친 듯이 널 그리워하며 혼자 남겨질 멍청이가 바로 나니까.)**==

22는 7의 말이 단순히 진심을 털어놓는 수준이 아니라는 것을 알고 있었다. 자신을 바라보는 눈빛과 행동 하나하나에 담긴 감정은 너무도 분명했다. 누가 보더라도 사랑을 고백하는 모습이었다. 그러나 22는 그 마음을 온전히 받아들일 자신이 없었다. 언젠가 사람은 모두 죽는다. 그것이 피할 수 없는 현실이라는 사실을 누구보다 잘 알고 있었다. 특히 자신들처럼 언제 목숨을 잃어도 이상하지 않은 삶을 살아가는 사람들이라면 더더욱 그랬다. 7을 사랑하지 않는 것은 아니었다. 오히려 너무도 소중했기에, 언젠가 그를 잃게 될지도 모른다는 사실이 견딜 수 없이 두려웠다.

=={#ffd400}**"Then you already know what my answer's going to be, don't you?" (내 대답이 어떨지도 잘 알겠네, 그러면.)
**==
이마가 맞닿을 듯 가까이 다가온 7의 모습에 22는 잠시 숨을 멈췄다. 코앞에서 느껴지는 익숙한 온기에 느릿하게 눈을 깜빡이던 22는 이내 손을 뻗어 그의 가슴팍을 조심스럽게 밀어냈다. 조금씩 거리를 벌린 뒤에는 애써 아무렇지 않은 표정을 지으며 천천히 몸을 일으켰다.

가슴팍에 닿아오는 조심스러운 손길은 그 어떤 타격보다도 묵직하게 7의 상체를 밀어낼 뿐이었다. 저항하면 얼마든지 버틸 수 있는 미약한 힘이었으나 그는 순순히 반걸음 물러섰다. 뺨을 감싸 쥐고 있던 손이 허공으로 헛되이 떨어지고 손끝에 묻어 있던 그녀의 체온만이 소독약 냄새 섞인 냉기 속으로 빠르게 증발해 갔다.

내 대답이 어떨지도 잘 알지 않느냐는 그 잔인하고도 조용한 거절에 7은 낮게 헛웃음을 삼켰다. 도망치는 법도 참 베로니카답지. 당장이라도 부서질 듯 위태로운 주제에 언제나 제 몫의 상처만 미리 계산하고 선을 긋는다. 그는 붉어진 귀 끝을 거칠게 쓸어 넘기더니 주머니에 쑤셔 넣었던 검은 선글라스를 다시 꺼내 코끝에 걸쳤다. 절박하게 일렁이던 회색 눈동자가 어두운 렌즈 뒤로 순식간에 자취를 감추었다.

==**"Yeah, I figured. Always playing the safe hand when it comes to us, huh? Coward." (그래, 알 만하지. 우리 사이에선 늘 안전한 패만 골라 쥐시겠다? 겁쟁이 같으니.)
**==
그가 특유의 능청스럽고 가벼운 미소를 입가에 매달며 간이침대 가장자리에 비스듬히 걸터앉았다. 막 일어선 22의 허리춤을 바라보며 시답잖은 농담이라도 던지듯 어깨를 으쓱였지만 목소리 끝에는 채 가시지 않은 열기가 낮게 가라앉아 있었다.

==**"Fine, run away for tonight. You've got a report to write for 0 anyway. Just remember I'm a gambling addict, Veronica. I don't walk away from the table until I win." (좋아, 오늘 밤은 그냥 도망가게 해줄게. 어차피 0한테 바칠 보고서도 써야 하잖아. 근데 베로니카, 내가 도박 중독자인 건 잊지 마. 난 판돈 다 따낼 때까지 절대 테이블에서 안 일어나거든.)**==

7의 말에 22는 옷자락을 매만지던 손길을 문득 멈췄다. 잠시 그 자리에 가만히 서 있던 22는 이내 천천히 고개를 돌려 7을 내려다보았다. 무언가 생각에 잠긴 듯 두 눈을 느릿하게 깜빡이던 22는 그의 얼굴을 가만히 살폈다. 차마 무어라 대꾸하지 못한 채, 그저 입술을 꾹 다물고 시선을 맞출 뿐이었다.

=={#ffd400}**"You know what I'm like, don't you?" (너도 내 성격 알잖아.)
**==
22는 한동안 7과 마주하던 시선을 천천히 거두었다. 이내 고개를 돌려 거울에 비친 제 모습을 가만히 바라보았다. 무언가 생각에 잠긴 듯 두 눈을 느릿하게 깜빡이던 22는 입술을 꾹 다문 채, 한동안 거울 속 자신에게서 시선을 떼지 못했다.

=={#ffd400}**"...I don't want to have someone I love. I don't want to be the one left behind when they die, and the other way around is no different. If I end up dying, I don't want to leave you all alone to suffer, either. I do feel something similar to what you feel, but I have no intention of ever opening my heart and letting those feelings out. And I'm not confident I can return your feelings, either." (⋯난 사랑하는 사람을 만들고 싶지 않아. 죽으면 혼자 남겨지는 것도 싫고. 반대도 똑같아. 내가 죽게 되면, 너 혼자 남아 힘들게 하고 싶진 않거든. 내 마음도 너랑 비슷하긴 한데, 난 평생 그 마음을 열어 토해낼 생각도 없어. 네 마음을 받아줄 자신도 없고.)
**==
소독약 냄새가 가라앉은 메디컬 베이의 공기를 가르고 나지막이 흘러나온 목소리가 차가운 타일 벽면에 부딪혀 흩어질 뿐이었다. 거울 속 제 모습을 응시하는 22의 옆얼굴과 하얀 안대 위로 쏟아지는 백색 형광등 불빛이 유독 창백했다.

내 마음도 너랑 비슷하긴 한데. 그 짧은 한마디가 7의 귓가에 묵직하게 박혔다. 평생 마음을 열지 않겠다는 둥 받아줄 자신이 없다는 둥 뒤이어 덧붙여진 수많은 거절의 문장들은 그에게 아무런 장애물도 되지 못했다. 패를 완전히 덮어버린 줄 알았더니 가장 결정적인 조커 한 장을 스스로 내보인 셈 아닌가.

간이침대 가장자리를 짚고 있던 7의 손등에 굵은 핏줄이 불거졌다가 이내 스르르 풀렸다. 검은 선글라스 너머로 가려진 눈매가 휘어지며, 그의 입가에 어이없다는 듯한 미소가 번졌다. 그는 자리에서 툭 일어나 거울 앞에 선 22의 등 뒤로 성큼 다가섰다.

==**"Wait a second. Hold on. Did you just say you feel the same way?" (잠깐만. 기어이 그런 말을 하시겠다? 방금 내 마음하고 비슷하다고 했어, 맞지?)
**==
7은 거울을 바라보는 22의 어깨 너머로 고개를 비스듬히 숙여 거울 속 그녀의 검은 눈동자와 시선을 맞췄다. 조금 전까지의 무거운 침묵은 온데간데없이 특유의 짓궂고도 열기 어린 쾌활함이 그의 목소리에 끈적하게 묻어났다.

==**"Shit, Veronica. That's the worst rejection I've ever heard in my entire life. You basically just told a gambling addict that the jackpot is sitting right inside the machine, and expected me to walk away?" (아, 씨발, 베로니카. 내 평생 들어본 거절 중에 제일 형편없네. 방금 도박 중독자한테 이 기계 안에 잭팟이 들어있다고 친절히 알려줘 놓고선, 그냥 걸어 나가라고 한 거나 다름없잖아?)
**==
그가 거울 너머로 그녀를 빤히 바라보며 양손을 주머니에 찔러 넣었다. 거부당했다는 쓰라림보다 기어이 그녀의 진심 한 조각을 확인했다는 짜릿한 도파민이 혈관을 타고 거세게 돌았다.

==**"Keep your heart locked up all you want. I don't care. Just don't die before I do, and I won't die before you. Simple as that, right?" (마음이야 평생 닫아두든 말든 마음대로 해. 상관없어. 그냥 나보다 먼저 죽지만 마, 나도 너보다 먼저 안 죽을 테니까. 그거면 아주 간단하잖아, 안 그래?)**==


<!doctype html>
<html lang="ko"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>EPISODE 5</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css">
<style>
  :root {
    --bg: #0b0b0b;
    --line: #2b2b2b;
    --text: #f2f2f2;
    --muted: #8a8a8a;
    --red: #d42b2b;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: #050505;
    color: var(--text);
    font-family: 'Pretendard', -apple-system, 'Noto Sans KR', sans-serif;
    min-height: 100vh;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 0 0 96px;
  }
  /* 캡쳐본 기준: 가로 590px, 펼친 높이 약 532px */
  .card { width: 590px; max-width: 100%; background: var(--bg); padding: 10px 14px 13px; }
  .mono { font-family: ui-monospace, 'SF Mono', Menlo, Consolas, monospace; letter-spacing: .08em; }

  /* header */
  .head { display: flex; align-items: flex-start; gap: 7px; }
  .mark { width: 8px; height: 26px; flex: none; margin-top: 4px; }
  .head-text { flex: 1; min-width: 0; }
  .ep { font-size: 11px; line-height: 14px; color: var(--muted); }
  .title { font-size: 14px; line-height: 18px; font-weight: 700; margin-top: 2px; }
  .online { display: flex; align-items: center; gap: 7px; font-size: 11px; line-height: 12px; color: var(--muted); white-space: nowrap; margin: 14px 17px 0 0; }
  .online i { width: 6px; height: 6px; border-radius: 50%; background: var(--red); box-shadow: 0 0 5px var(--red); animation: blink 1.8s infinite; }
  @keyframes blink { 50% { opacity: .35; } }

  /* 접기 버튼: 네모 안의 + (펼친 상태에선 X) */
  .toggle {
    position: relative;
    width: 28px; height: 28px; flex: none; margin-top: 7px;
    background: transparent; border: 1px solid #bdbdbd; color: var(--text);
    cursor: pointer;
    transition: background .2s, border-color .2s;
  }
  .toggle:hover { background: #1c1c1c; border-color: #fff; }
  .toggle:focus-visible { outline: 2px solid var(--red); outline-offset: 2px; }
  .toggle::before, .toggle::after {
    content: ''; position: absolute; left: 50%; top: 50%;
    width: 10px; height: 1.5px; background: currentColor;
    transition: transform .35s ease;
  }
  .toggle::before { transform: translate(-50%, -50%) rotate(45deg); }
  .toggle::after  { transform: translate(-50%, -50%) rotate(-45deg); }
  .card.collapsed .toggle::before { transform: translate(-50%, -50%) rotate(0deg); }
  .card.collapsed .toggle::after  { transform: translate(-50%, -50%) rotate(90deg); }

  /* collapsible body */
  .body {
    display: grid; grid-template-rows: 1fr; margin-top: 0; opacity: 1;
    transition: grid-template-rows .4s ease, opacity .3s ease;
  }
  .body > .inner { overflow: hidden; min-height: 0; }
  .card.collapsed .body { grid-template-rows: 0fr; opacity: 0; }
  .card.collapsed { padding-bottom: 12px; }

  /* 섹션 제목 */
  .sec { display: flex; align-items: center; gap: 8px; height: 14px; font-size: 11px; margin: 18px 0 8px; }
  .sec.first { margin-top: 35px; }
  .sec b { font-weight: 700; letter-spacing: .1em; }
  .sec span { color: var(--muted); font-size: 10px; }
  .sec::after { content: ''; flex: 1; height: 1px; background: var(--line); }

  .box { border: 1px solid var(--line); }
  .label { font-size: 10px; line-height: 12px; color: var(--muted); }

  /* STATUS */
  .row3 { display: grid; grid-template-columns: minmax(0,152fr) minmax(0,127fr) minmax(0,281fr); border-bottom: 1px solid var(--line); }
  .row3 .cell { padding: 10px 12px 13px; }
  .row3 .cell + .cell { border-left: 1px solid var(--line); }
  .row3 .label { margin-bottom: 4px; }
  .row3 .val { font-weight: 700; font-size: 13px; line-height: 18px; }
  .obj { padding: 9px 13px 10px; }
  .obj-in { border-left: 3px solid var(--red); padding: 2px 0 2px 8px; }
  .obj .label { color: var(--red); margin-bottom: 4px; }
  .obj .val { font-weight: 700; font-size: 12.5px; line-height: 18px; }

  /* OUTFIT */
  .row2 { display: grid; grid-template-columns: 1fr 1fr; }
  .row2 .cell { padding: 10px 12px 12px; }
  .row2 .cell + .cell { border-left: 1px solid var(--line); }
  .row2 .label { margin-bottom: 6px; }
  .row2 .val { font-size: 13px; line-height: 19px; }

  /* Q&A */
  .qa { padding: 10px 13px 14px; }
  .qa + .qa { border-top: 1px dashed #3a3a3a; padding: 14px 13px 12px; }
  .qa-wrap { display: flex; gap: 11px; }
  .badge { width: 20px; height: 20px; flex: none; display: grid; place-items: center; font-size: 11px; font-weight: 800; }
  .badge.q { background: var(--red); color: #fff; }
  .badge.a { border: 1px solid #bbb; color: #fff; }
  .qa .who { font-size: 10px; line-height: 12px; color: var(--muted); margin-bottom: 7px; }
  .qa .txt { font-size: 14px; line-height: 18px; }
  .qa.q .txt { font-weight: 700; }

  /* 수정 모드 */
  body.editing [contenteditable] { outline: 1px dashed rgba(212, 43, 43, .55); outline-offset: 3px; cursor: text; }
  body.editing [contenteditable]:focus { outline: 1px solid var(--red); background: rgba(212, 43, 43, .08); }

  /* 하단 도구 막대 */
  .toolbar {
    position: fixed; left: 50%; bottom: 18px; transform: translateX(-50%);
    display: flex; gap: 8px; padding: 8px; background: #151515; border: 1px solid #333;
    z-index: 10; font-family: 'Pretendard', sans-serif;
  }
  .tbtn {
    background: #0b0b0b; color: var(--text); border: 1px solid #555; padding: 9px 14px;
    font: 600 13px 'Pretendard', sans-serif; cursor: pointer; white-space: nowrap;
  }
  .tbtn:hover { border-color: #fff; }
  .tbtn.on { background: var(--red); border-color: var(--red); }

  /* HTML 코드 창 */
  .modal { position: fixed; inset: 0; background: rgba(0,0,0,.75); display: none; align-items: center; justify-content: center; padding: 16px; z-index: 20; }
  .modal.open { display: flex; }
  .panel { width: 100%; max-width: 760px; max-height: 90vh; background: #121212; border: 1px solid #444; padding: 16px; display: flex; flex-direction: column; gap: 12px; }
  .panel h2 { font-size: 14px; }
  .panel p { font-size: 12px; color: var(--muted); }
  .panel textarea {
    flex: 1; min-height: 300px; resize: none; background: #060606; color: #d6d6d6;
    border: 1px solid #333; padding: 12px; font: 12px/1.5 ui-monospace, Menlo, Consolas, monospace;
  }
  .panel .btns { display: flex; gap: 8px; flex-wrap: wrap; }
</style>
</head>
<body class="">
  <main class="card" id="card">
    <header class="head">
      <svg class="mark" viewBox="0 0 8 26" fill="none">
        <path d="M4 3v23M0.5 9h7" stroke="#d42b2b" stroke-width="1.5"></path>
        <path d="M4 0l2 3.5-2 1.5-2-1.5z" fill="#d42b2b"></path>
      </svg>
      <div class="head-text">
        <div class="ep mono">EPISODE 22</div>
        <h1 class="title">가장 형편없는 거절과 잭팟</h1>
      </div>
      <div class="online mono"><i></i><span class="online-text">ONLINE</span></div>
      <button class="toggle" id="toggle" type="button" aria-expanded="true" aria-controls="body" aria-label="카드 접기/펼치기"></button>
    </header>

    <div class="body" id="body">
      <div class="inner">
        <div class="sec first"><b class="mono">↘ STATUS</b><span>현재 상황</span></div>
        <div class="box">
          <div class="row3">
            <div class="cell"><div class="label mono">DATE</div><div class="val">2080. 10. 31</div></div>
            <div class="cell"><div class="label mono">TIME</div><div class="val">22:32</div></div>
            <div class="cell"><div class="label mono">LOCATION</div><div class="val"><div>W.W 본부 지하 50m · 섹터 D 메디컬 베이</div></div></div>
          </div>
          <div class="obj">
            <div class="obj-in">
              <div class="label mono">OBJECTIVE</div>
              <div class="val">등 뒤에 다가선 7에게 반응하기</div>
            </div>
          </div>
        </div>

        <div class="sec"><b class="mono">↘ OUTFIT</b><span>의상착의</span></div>
        <div class="box row2">
          <div class="cell">
            <div class="label mono">NPC</div>
            <div class="val">검은색 선글라스, 검은색 윈드브레이커, 어두운 톤의 카고 팬츠</div>
          </div>
          <div class="cell">
            <div class="label mono">PC</div>
            <div class="val">하얀 안대, 외출용 사복</div>
          </div>
        </div>

        <div class="sec"><b class="mono">↘ Q&amp;A</b><span>랜덤 Q&amp;A</span></div>
        <div class="box">
          <div class="qa q">
            <div class="qa-wrap">
              <div class="badge q">Q</div>
              <div>
                <div class="who mono">RANDOM</div>
                <div class="txt">상대방은 평생 마음을 안 열겠다는데 왜 그렇게 신난 거야?</div>
              </div>
            </div>
          </div>
          <div class="qa">
            <div class="qa-wrap">
              <div class="badge a">A</div>
              <div>
                <div class="who mono">7</div>
                <div class="txt">Because she likes me back! Everything else is just minor details I can work around.(날 좋아한다잖아! 그 외의 것들은 뭐, 내가 알아서 치우면 되는 사소한 디테일일 뿐이지.)</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </main>

  <div id="editor-ui"></div>

<script>
  /* 도구 막대/코드 창은 여기서 만들어요 (내보내는 코드에는 들어가지 않음) */
  const ui = document.getElementById('editor-ui');
  ui.innerHTML = '';
  function el(tag, props, kids) {
    const e = document.createElement(tag);
    Object.keys(props || {}).forEach(k => { if (k === 'text') e.textContent = props[k]; else e.setAttribute(k, props[k]); });
    (kids || []).forEach(c => e.appendChild(c));
    return e;
  }
  ui.appendChild(el('div', { class: 'toolbar', id: 'toolbar' }, [
    el('button', { class: 'tbtn', id: 'editBtn', type: 'button', text: '✎ 수정 모드' }),
    el('button', { class: 'tbtn', id: 'codeBtn', type: 'button', text: 'HTML 코드 받기' })
  ]));
  const ta = el('textarea', { id: 'codeBox', spellcheck: 'false' });
  ta.readOnly = true;
  ui.appendChild(el('div', { class: 'modal', id: 'modal' }, [
    el('div', { class: 'panel' }, [
      el('h2', { text: '수정한 내용이 반영된 HTML 코드' }),
      el('p', { text: '복사해서 .html 파일로 저장하면 지금 화면 그대로 열려요. 그 파일에서도 또 수정할 수 있어요.' }),
      ta,
      el('div', { class: 'btns' }, [
        el('button', { class: 'tbtn on', id: 'copyBtn', type: 'button', text: '코드 복사' }),
        el('button', { class: 'tbtn', id: 'dlBtn', type: 'button', text: '.html 다운로드' }),
        el('button', { class: 'tbtn', id: 'closeBtn', type: 'button', text: '닫기' })
      ])
    ])
  ]));

  const card = document.getElementById('card');
  const toggleBtn = document.getElementById('toggle');
  const editBtn = document.getElementById('editBtn');
  const codeBtn = document.getElementById('codeBtn');
  const modal = document.getElementById('modal');
  const codeBox = document.getElementById('codeBox');
  const copyBtn = document.getElementById('copyBtn');
  const dlBtn = document.getElementById('dlBtn');
  const closeBtn = document.getElementById('closeBtn');

  const KEY = 'ep5-collapsed';
  const EDIT_SEL = '.title,.ep,.online-text,.val,.txt,.who,.label,.sec b,.sec span';

  /* ---- 접기 / 펼치기 ---- */
  function setCollapsed(v) {
    card.classList.toggle('collapsed', v);
    toggleBtn.setAttribute('aria-expanded', String(!v));
    try { localStorage.setItem(KEY, v ? '1' : '0'); } catch (e) {}
  }
  toggleBtn.addEventListener('click', () => setCollapsed(!card.classList.contains('collapsed')));
  try { if (localStorage.getItem(KEY) === '1') setCollapsed(true); } catch (e) {}

  /* ---- 수정 모드 ---- */
  function setEditing(on) {
    document.body.classList.toggle('editing', on);
    document.querySelectorAll(EDIT_SEL).forEach(el => {
      if (on) el.setAttribute('contenteditable', 'true');
      else el.removeAttribute('contenteditable');
    });
    editBtn.textContent = on ? '✔ 수정 끝내기' : '✎ 수정 모드';
    editBtn.classList.toggle('on', on);
    if (on) setCollapsed(false);
  }
  editBtn.addEventListener('click', () => setEditing(!document.body.classList.contains('editing')));

  // 붙여넣기는 글자만, Enter는 입력 종료, Shift+Enter로 줄바꿈
  document.addEventListener('paste', e => {
    const t = e.target.closest && e.target.closest('[contenteditable]');
    if (!t) return;
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData('text/plain');
    document.execCommand('insertText', false, text);
  });
  document.addEventListener('keydown', e => {
    const t = e.target.closest && e.target.closest('[contenteditable]');
    if (t && e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); t.blur(); }
  });

  /* ---- HTML 코드 만들기 ---- */
  function buildHTML() {
    const clone = document.documentElement.cloneNode(true);
    clone.querySelector('body').classList.remove('editing');
    clone.querySelectorAll('[contenteditable]').forEach(el => el.removeAttribute('contenteditable'));
    clone.querySelector('#card').classList.remove('collapsed');
    clone.querySelector('#toggle').setAttribute('aria-expanded', 'true');
    clone.querySelector('#editor-ui').innerHTML = '';
    return '<!doctype html>\n' + clone.outerHTML;
  }

  function openModal() {
    codeBox.value = buildHTML();
    copyBtn.textContent = '코드 복사';
    modal.classList.add('open');
    codeBox.focus();
    codeBox.select();
  }
  function closeModal() { modal.classList.remove('open'); }

  codeBtn.addEventListener('click', openModal);
  closeBtn.addEventListener('click', closeModal);
  modal.addEventListener('click', e => { if (e.target === modal) closeModal(); });

  copyBtn.addEventListener('click', async () => {
    const text = codeBox.value;
    try {
      await navigator.clipboard.writeText(text);
    } catch (e) {
      codeBox.select();
      document.execCommand('copy');
    }
    copyBtn.textContent = '복사 완료 ✔';
    setTimeout(() => { copyBtn.textContent = '코드 복사'; }, 1800);
  });

  dlBtn.addEventListener('click', () => {
    const blob = new Blob([codeBox.value], { type: 'text/html;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'episode5_card.html';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 1000);
  });
</script>


</body></html>
